def eulerian_number(n, m):
    if m >= n or n == 0:
        return 0
    if m == 0:
        return 1
    first_term = (n - m) * eulerian_number(n - 1, m - 1)
    second_term = (m + 1) * eulerian_number(n - 1, m)
    return first_term + second_term

