def find_x_y(a, b, n):
    from math import gcd
    g = gcd(a, b)
    if n % g != 0:
        return None
    x0, y0 = 0, 0
    if a == 0:
        if b == 0:
            return None if n != 0 else (0, 0)
        return 0, n // b
    inv_a, inv_b = b, a
    while a != 0:
        inv_a, a = a, inv_a % a
        inv_b, b = b - inv_a // a * inv_b, inv_b
    x0 = (n // g) * inv_b
    y0 = (n // g) * (-inv_a)
    return (x0, y0)

