def max_bitonic_sum(arr):
    n = len(arr)
    inc = [0] * n
    dec = [0] * n

    inc[0] = arr[0]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j]:
                inc[i] = inc[j]
        inc[i] += arr[i]

    dec[n - 1] = arr[n - 1]
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j]:
                dec[i] = dec[j]
        dec[i] += arr[i]

    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

