def max_subarray_sum_repeated(arr, k):
    def max_kadane(arr):
        max_end_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_end_here = max(x, max_end_here + x)
            max_so_far = max(max_so_far, max_end_here)
        return max_so_far

    n = len(arr)
    if k == 1:
        return max_kadane(arr)

    prefix_sum = 0
    max_prefix_sum = float('-inf')
    for i in range(n):
        prefix_sum += arr[i]
        max_prefix_sum = max(max_prefix_sum, prefix_sum)

    suffix_sum = 0
    max_suffix_sum = float('-inf')
    for i in range(n - 1, -1, -1):
        suffix_sum += arr[i]
        max_suffix_sum = max(max_suffix_sum, suffix_sum)

    total_sum = sum(arr)
    if total_sum > 0:
        return max(max_kadane(arr * 2), max_prefix_sum + max_suffix_sum + (k - 2) * total_sum)
    else:
        return max_kadane(arr * 2)

